17	// ---------- 测试辅助 ----------
18	
19	func mustRegisterCompartment(t *testing.T, r *Registry, id string, maxWeight int64) {
20		t.Helper()
21		if err := r.RegisterCompartment(id, maxWeight); err != nil {
22			t.Fatalf("登记舱位 %s 失败: %v", id, err)
23		}
24	}
