		t.Fatalf("G2 登记资料不应被改写: %+v", g2)
	}

	// 预览后登记状态不变。
	cv, _ := r.Cargo("G1")
	if cv.Loaded || cv.CompartmentID != "" {
		t.Fatalf("预览不应改变货物状态: %+v", cv)
	}
}

func TestPreviewSwapAfterListsShowSwappedPositions(t *testing.T) {
	r := NewRegistry()
	if err := r.RegisterCompartment("C1", 30); err != nil {
		t.Fatal(err)
	}
